def midpoint(p1, p2):
    r1, c1 = p1
    r2, c2 = p2
    # Check if same row, same col, or forms 90-degree corner
    if r1 == r2:
        return None  # Already covered by line-between
    elif c1 == c2:
        return None
    elif abs(r1-r2) == abs(c1-c2):
        # Diagonal, check if integer midpoint exists
        dr = r2 - r1
        dc = c2 - c1
        # Midpoint: ((r1+r2)/2, (c1+c2)/2)
        mr, mc = (r1+r2)//2, (c1+c2)//2
        if mr != (r1+r2)/2 or mc != (c1+c2)/2:
            return None
        return (mr, mc)
    return None

