def get_diagonal_cells(p1, p2):
    """Get cells on perfect diagonal between two points"""
    r1, c1 = p1
    r2, c2 = p2

    dr = abs(r2 - r1)
    dc = abs(c2 - c1)

    if dr != dc:
        return None  # Not a perfect diagonal

    steps = min(dr, dc)
    if steps == 0:
        return [p1]

    result = []
    if (r2 > r1) == (c2 > c1):
        step_r, step_c = 1, 1  # Both increasing or both decreasing
    else:
        step_r, step_c = 1, -1

    for i in range(steps + 1):
        result.append((r1 + i * step_r, c1 + i * step_c))

    return result

