# What if we need a specific type of ray? Like only cardinal directions (no diagonals)?

def get_cardinal_rays(points):
    """Get all cells on straight LINE (not line segment) from one point toward another,
    going in only horizontal or vertical direction"""
    result = set()
    for i, p1 in enumerate(points):
        for j, p2 in enumerate(points):
            if i == j:
                continue
            r1, c1 = p1
            r2, c2 = p2

            dr = r2 - r1
            dc = c2 - c1

            # Only horizontal or vertical lines
            if dr != 0 and dc != 0:
                continue  # Diagonal, skip

            # Determine direction and trace
            num_steps = max(abs(dr), abs(dc))

            if dr != 0:
                step = -1 if dr < 0 else 1
                for offset in range(num_steps + 1):
                    result.add((r1 + offset * step, c1))
            else:
                step = -1 if dc < 0 else 1
                for offset in range(num_steps + 1):
                    result.add((r1, c1 + offset * step))

    return result

