from collections import deque

def manhattan_path(p1, p2, obstacles=None):
    """Get Manhattan path from p1 to p2, preferring straight lines first"""
    r1, c1 = p1
    r2, c2 = p2

    # Check if direct straight line works
    dr = r2 - r1
    dc = c2 - c1

    result = [p1]

    if dr == 0:
        # Horizontal
        step = -1 if dc < 0 else 1
        for col in range(c1 + step, c2, step):
            result.append((r1, col))
        result.append(p2)
    elif dc == 0:
        # Vertical
        step = -1 if dr < 0 else 1
        for row in range(r1 + step, r2, step):
            result.append((row, c1))
        result.append(p2)
    else:
        # L-shaped path - need to decide corner
        # First vertical then horizontal, or vice versa
        corners = [(r2, c1), (r1, c2)]

        for corner in corners:
            # Try this corner
            path = []
            path.append(p1)

            # First segment (vertical)
            if corner[0] != r1:
                step = -1 if corner[0] < r1 else 1
                for row in range(r1 + step, corner[0], step):
                    path.append((row, c1))

            # Second segment (horizontal)
            if corner[1] != c1:
                step = -1 if corner[1] < c1 else 1
                for col in range(c1 + step, corner[1], step):
                    path.append((r1, col))

            # Third part to reach destination
            if corner[0] != r2:
                step = -1 if corner[0] < r2 else 1
                for row in range(corner[0] + step, r2, step):
                    path.append((row, corner[1]))

            if corner[1] != c2:
                step = -1 if corner[1] < c2 else 1
                path.extend(((r1, col) for col in range(corner[1] + step, c2, step)))
                path.append(p2)

            # Check if path hits obstacles (other 2s)
            obstacles_in_path = False
            oblist = list(obstacles) if obstacles else set()
            for cell in path[1:-1]:  # Skip endpoints
                if cell in oblist:
                    obstacles_in_path = True
                    break

            if not obstacles_in_path:
                return path

        # Neither corner worked, try both and pick shorter or arbitrary
        pass

    return None

