# Try: each 2 shoots toward ALL OTHER 2s, extending beams only up to reaching/passing them

def simulate_toward_others(grid_input):
    h, w = len(grid_input), len(grid_input[0])

    result = [[grid_input[r][c] for c in range(w)] for r in range(h)]

    twos = [(r, c) for r in range(h) for c in range(w) if grid_input[r][c] == 2]

    for src_r, src_c in twos:
        for tr, tc in twos:
            if src_r == tr and src_c == tc:
                continue

            # Direction from source to target
            dr = tr - src_r
            dc = tc - src_c

            num_steps = max(abs(dr), abs(dc))

            step_r = dr / num_steps if num_steps > 0 else 0
            step_c = dc / num_steps if num_steps > 0 else 0

            # Trace the line, setting 3s along the way
            for i in range(num_steps + 1):
                if result[int(src_r + i * step_r)][int(src_c + i * step_c)] == 2:
                    break  # Stop at the target
                r, c = int(src_r + i * step_r), int(src_c + i * step_c)
                result[r][c] = 3

    return result

