# Try finding the right box size
def solve_with_box_size(grid, box_radius):
    """Fill 3s in box of given radius around each 2"""
    h, w = len(grid), len(grid[0])

    twos = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]

    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    for r, c in twos:
        # Generate cells in box
        for dr in range(-box_radius, box_radius + 1):
            for dc in range(-box_radius, box_radius + 1):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    result[nr][nc] = 3

    return result

